 * ```
 */
export type SchemaToNonRef<Schema extends SchemaType> =
  Schema extends OasRef<'schema'> ? never : Schema

/**
 * Gets the output type for a given schema type key.
 *
 * @template T - The schema type key
 * @example
 * ```typescript
