  context: GenerateContextType
  modifiers: Modifiers
  schema: OasBoolean
  destinationPath: string
  generatorKey: GeneratorKey
}

export class TypeboxBoolean extends TsSnippet {
  type = 'boolean' as const
  modifiers: Modifiers
